          <PortfolioGreeksPanel greeks={portfolioGreeks} />
          {isReplayDone && (
            <p className="text-xs text-muted">
              This account has used all of its simulated price history — trading
              here has ended.
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

