  ["stop",   "short", 580, true ],
  ["stop",   "short", 600, false],
] as const)("valid=%j : %s %s @ %d (spot 590)", (_t, _s, _trig, valid) => {
  void _t; void _s; void _trig;
  expect(validateTrigger(_t as any, _s as any, _trig, SPOT))[valid ? "toBeNull" : "toBeTruthy"]();
});
